import { FileUpIcon } from 'lucide-react';
import { useState } from 'react';
import { InputError } from '@/components/company-os/field-row';
import { ImportPreviewSection } from '@/components/company-os/import-preview';
import type { ImportPreview, ImportPreviewLabels } from '@/components/company-os/import-preview';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { OptionSelect } from '@/components/ui/option-select';

export type CsvImportLabels = {
    file: string;
    existing: string;
    skip: string;
    update: string;
    preview: string;
    import: (count: number, noun: string) => string;
};

export const csvImportLabels: CsvImportLabels = {
    file: 'CSV file',
    existing: 'Rows that already exist',
    skip: 'Skip existing',
    update: 'Update existing',
    preview: 'Preview import',
    import: (count, noun) => `Import ${count} ${noun}`,
};

export function CsvImport({
    noun,
    help,
    detailLabel,
    preview,
    processing,
    fileError,
    onPreview,
    onImport,
    labels = csvImportLabels,
    previewLabels,
}: {
    noun: string;
    help: string;
    detailLabel: string;
    preview: ImportPreview | null;
    processing: boolean;
    fileError?: string;
    onPreview: (file: File, updateExisting: boolean) => void;
    onImport: (file: File, updateExisting: boolean) => void;
    labels?: CsvImportLabels;
    previewLabels?: ImportPreviewLabels;
}) {
    const [file, setFile] = useState<File | null>(null);
    const [previewed, setPreviewed] = useState<{ file: File; updateExisting: boolean } | null>(null);
    const [mode, setMode] = useState('skip');
    const updateExisting = mode === 'update';
    const current = preview !== null && previewed?.file === file && previewed.updateExisting === updateExisting;
    const changes = current && preview ? preview.creates.length + preview.updates.length : 0;

    return (
        <>
            <div className="max-w-2xl rounded-lg glass p-6">
                <div className="grid gap-4">
                    <div className="grid gap-2">
                        <Label htmlFor="csv-file">{labels.file}</Label>
                        <Input
                            id="csv-file"
                            type="file"
                            accept=".csv,.txt,text/csv"
                            onChange={(event) => setFile(event.target.files?.[0] ?? null)}
                        />
                        <InputError message={fileError} />
                        <p className="text-sm text-muted-foreground">{help}</p>
                    </div>
                    <div className="grid gap-2">
                        <Label>{labels.existing}</Label>
                        <OptionSelect
                            aria-label={labels.existing}
                            value={mode}
                            onValueChange={setMode}
                            options={[
                                { value: 'skip', label: labels.skip },
                                { value: 'update', label: labels.update },
                            ]}
                        />
                    </div>
                    <div className="flex gap-2">
                        <Button
                            variant={current ? 'outline' : 'default'}
                            disabled={file === null || processing}
                            onClick={() => {
                                if (file) {
                                    setPreviewed({ file, updateExisting });
                                    onPreview(file, updateExisting);
                                }
                            }}
                        >
                            <FileUpIcon />
                            {labels.preview}
                        </Button>
                        {current && (
                            <Button disabled={changes === 0 || processing || file === null} onClick={() => file && onImport(file, updateExisting)}>
                                {labels.import(changes, noun)}
                            </Button>
                        )}
                    </div>
                </div>
            </div>
            {current && preview && <ImportPreviewSection preview={preview} detailLabel={detailLabel} labels={previewLabels} />}
        </>
    );
}

import { FileSpreadsheetIcon } from 'lucide-react';
import { EmptyState } from '@/components/company-os/empty-state';
import { Pill } from '@/components/company-os/pill';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';

export type ImportRowView = {
    line: number;
    name: string;
    detail: string | null;
    note: string | null;
    warnings: string[];
};

export type ImportPreview = Record<'creates' | 'updates' | 'duplicates' | 'invalid', ImportRowView[]>;

export type ImportPreviewLabels = {
    creates: string;
    updates: string;
    duplicates: string;
    invalid: string;
    line: string;
    name: string;
    note: string;
    emptyTitle: string;
    emptyMessage: string;
};

export const importPreviewLabels: ImportPreviewLabels = {
    creates: 'New',
    updates: 'Updates',
    duplicates: 'Skipped',
    invalid: 'Rows with errors',
    line: 'Line',
    name: 'Name',
    note: 'Note',
    emptyTitle: 'No rows found',
    emptyMessage: 'The file has a header but no rows under it.',
};

const sections: { key: keyof ImportPreview; color: string }[] = [
    { key: 'creates', color: 'emerald' },
    { key: 'updates', color: 'indigo' },
    { key: 'duplicates', color: 'cyan' },
    { key: 'invalid', color: 'rose' },
];

export function ImportPreviewSection({
    preview,
    detailLabel,
    labels = importPreviewLabels,
}: {
    preview: ImportPreview;
    detailLabel: string;
    labels?: ImportPreviewLabels;
}) {
    if (sections.every(({ key }) => preview[key].length === 0)) {
        return <EmptyState icon={FileSpreadsheetIcon} title={labels.emptyTitle} message={labels.emptyMessage} />;
    }

    return (
        <div className="grid gap-6">
            {sections
                .filter(({ key }) => preview[key].length > 0)
                .map(({ key, color }) => (
                    <section key={key} className="rounded-lg glass">
                        <div className="flex items-center gap-2 border-b border-border px-5 py-3.5">
                            <h2 className="text-sm font-semibold text-slate-800">{labels[key]}</h2>
                            <Pill name={String(preview[key].length)} color={color} />
                        </div>
                        <Table>
                            <TableHeader>
                                <TableRow>
                                    <TableHead className="w-16">{labels.line}</TableHead>
                                    <TableHead>{labels.name}</TableHead>
                                    <TableHead>{detailLabel}</TableHead>
                                    <TableHead>{labels.note}</TableHead>
                                </TableRow>
                            </TableHeader>
                            <TableBody>
                                {preview[key].map((row) => (
                                    <TableRow key={row.line}>
                                        <TableCell className="font-mono text-xs text-muted-foreground">{row.line}</TableCell>
                                        <TableCell className="font-medium text-slate-800">{row.name || '—'}</TableCell>
                                        <TableCell>{row.detail ?? '—'}</TableCell>
                                        <TableCell className={key === 'invalid' ? 'text-rose-600' : 'text-muted-foreground'}>
                                            {row.note}
                                            {row.warnings.map((warning) => (
                                                <span key={warning} className="block text-xs text-rose-600">
                                                    {warning}
                                                </span>
                                            ))}
                                        </TableCell>
                                    </TableRow>
                                ))}
                            </TableBody>
                        </Table>
                    </section>
                ))}
        </div>
    );
}
